/* MedicCare.module.css — faithful port of Medic Care (Templatemo) */

.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #565758;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: 'Open Sans', sans-serif;
  position: relative;
}

/* ---------- Navigation ---------- */
.nav {
  background: var(--vt-surface);
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  padding-top: 20px;
  padding-bottom: 20px;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1rem;
}

.logo {
  color: var(--vt-accent);
  font-size: 24px;
  font-weight: 700;
  text-decoration: none;
  line-height: 1.2;
  text-align: center;
}

.brand {
  display: block;
}

.navLinks {
  display: flex;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  text-decoration: none;
  padding: 15px 0;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus-visible {
  color: var(--vt-ink);
}

/* ---------- Hero ---------- */
.hero {
  position: relative;
  padding-top: 94px; /* offset for fixed nav */
  background: var(--vt-surface);
}

.heroSlides {
  position: relative;
  height: 580px;
  overflow-x: auto;
  overflow-y: hidden;
  display: flex;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.heroSlides::-webkit-scrollbar {
  display: none;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  position: relative;
}

.heroImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
}

.heroTitle {
  font-size: 48px;
  font-weight: 700;
  line-height: normal;
  margin: 0 0 0.5rem;
  color: var(--vt-ink);
}

.animatedItem {
  color: var(--vt-accent);
}

.heroP {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  margin-right: 1.5rem;
  transition: all 0.3s;
  position: relative;
  overflow: hidden;
  background: transparent;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  right: 0;
  text-align: center;
  transition: all 300ms cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin: 0;
  display: flex;
  align-items: center;
}

.phoneIcon {
  margin-right: 0.5rem;
  color: var(--vt-accent);
}

/* ---------- About ---------- */
.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

.aboutRow {
  display: flex;
  justify-content: center;
}

.aboutText {
  max-width: 800px;
  width: 100%;
}

.aboutH2 {
  font-size: 36px;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
}

.aboutText p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.8;
  margin-bottom: 1rem;
}

/* ---------- Gallery ---------- */
.gallery {
  background: var(--vt-surface);
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 1 1 50%;
  max-width: 50%;
}

.galleryImg {
  width: 100%;
  height: auto;
  display: block;
}

/* ---------- Timeline ---------- */
.pb0 {
  padding-bottom: 0;
}

.timelineHeader {
  text-align: center;
  margin-bottom: 4rem;
}

.timelineH2 {
  font-size: 36px;
  font-weight: 700;
  color: var(--vt-ink);
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  display: block;
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.timelineNode {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 2.5rem;
}

.timelineNode:nth-child(even) {
  flex-direction: row-reverse;
}

.timelineContent {
  position: relative;
  width: 45%;
  background: var(--vt-surface);
  border-radius: 0 0 0.25rem 0.25rem;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  padding-bottom: 1.5rem;
}

.timelineTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
  font-size: 32px;
  font-weight: 600;
}

.timelineNode:nth-child(odd) .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode:nth-child(even) .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineContent p {
  color: var(--vt-ink-soft);
  padding: 10px 30px 0;
  margin: 0;
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.7;
}

.timelineIconWrap {
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  width: 80px;
  height: 80px;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
}

.timelineIcon {
  font-size: 32px;
  color: var(--vt-accent);
  line-height: 1;
}

.timelineDate {
  width: 45%;
  padding-top: 20px;
  font-weight: 600;
  color: var(--vt-ink-soft);
}

.timelineNode:nth-child(odd) .timelineDate {
  text-align: left;
}

.timelineNode:nth-child(even) .timelineDate {
  text-align: right;
}

/* ---------- Footer ---------- */
.siteFooter {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  align-items: flex-start;
}

.footerHours,
.footerClinic,
.footerSocial,
.footerCopyright {
  flex: 1 1 200px;
  min-width: 200px;
}

.footerHours h5,
.footerClinic h5,
.footerSocial h5 {
  font-size: 24px;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
}

.footerHours p,
.footerClinic p,
.footerCopyright p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.7;
  margin: 0 0 0.5rem;
}

.footerSocial a {
  color: var(--vt-ink-soft);
  font-size: 18px;
  margin-right: 15px;
  transition: color 0.3s;
}

.footerSocial a:hover {
  color: var(--vt-accent);
}

.footerCopyright p {
  font-size: 16px;
}

/* ---------- Responsive ---------- */
@media screen and (min-width: 1600px) {
  .heroSlides {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .navLinks a {
    padding-top: 5px;
    padding-bottom: 10px;
  }

  .heroSlides {
    height: inherit;
  }

  .heroText {
    position: relative;
    bottom: 100px;
    left: 0;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }

  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .heroTitle {
    font-size: 38px;
  }

  .aboutH2,
  .timelineH2 {
    font-size: 32px;
  }

  .timeline::before {
    left: 33px;
    transform: none;
    top: 60px;
    height: 90%;
  }

  .timelineNode,
  .timelineNode:nth-child(even) {
    flex-direction: column;
    align-items: flex-start;
    padding-left: 90px;
  }

  .timelineContent,
  .timelineDate {
    width: 100%;
  }

  .timelineIconWrap {
    left: 0;
    top: 60px;
    transform: none;
    width: 75px;
    height: 75px;
  }

  .timelineNode:nth-child(odd) .timelineTitle::after,
  .timelineNode:nth-child(even) .timelineTitle::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
  }

  .timelineNode:nth-child(even) .timelineDate,
  .timelineNode:nth-child(odd) .timelineDate {
    text-align: left;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 57px;
    height: 87%;
  }

  .timelineIconWrap {
    left: -10px;
    width: 70px;
    height: 70px;
  }

  .timelineIcon {
    font-size: 28px;
  }

  .heroText {
    padding: 1rem;
  }

  .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .customLink {
    font-size: 12px;
    line-height: 30px;
    margin-right: 12px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }

  .timelineIconWrap {
    width: 60px;
    height: 60px;
  }

  .timelineIcon {
    font-size: 24px;
  }
}
